// AI-code-start lines:22 tool:Codex
export function pageWindow(total, page, pageSize) {
  // 非有限数值不能形成稳定窗口，分别回退到对应的安全边界。
  const normalizedTotal = Number.isFinite(total) ? Math.max(0, Math.floor(total)) : 0;
  const normalizedPageSize = Number.isFinite(pageSize) ? Math.max(1, Math.floor(pageSize)) : 1;
  const totalPages = Math.ceil(normalizedTotal / normalizedPageSize);

  if (totalPages === 0) {
    return {
      page: 1,
      totalPages: 0,
      start: 0,
      end: 0,
    };
  }

  const requestedPage = Number.isFinite(page) ? Math.floor(page) : 1;
  const normalizedPage = Math.min(Math.max(1, requestedPage), totalPages);

  return {
    page: normalizedPage,
    totalPages,
    start: (normalizedPage - 1) * normalizedPageSize + 1,
    end: Math.min(normalizedPage * normalizedPageSize, normalizedTotal),
  };
}

